-- Custom tenant-scoped grants. Bootstrap administrators remain in user_churches and cannot be removed here.
CREATE TABLE roles (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), name TEXT NOT NULL, UNIQUE(churchId,id));
CREATE INDEX roles_church_name ON roles(churchId,name);
CREATE TABLE role_permissions (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), roleId TEXT NOT NULL, apiName TEXT NOT NULL, contentType TEXT NOT NULL, contentId TEXT NOT NULL DEFAULT '', action TEXT NOT NULL, UNIQUE(churchId,roleId,apiName,contentType,contentId,action), FOREIGN KEY(churchId,roleId) REFERENCES roles(churchId,id) ON DELETE CASCADE);
CREATE TABLE role_members (id TEXT PRIMARY KEY, churchId TEXT NOT NULL REFERENCES churches(id), roleId TEXT NOT NULL, userId TEXT NOT NULL, addedBy TEXT NOT NULL, dateAdded TEXT NOT NULL, UNIQUE(churchId,roleId,userId), FOREIGN KEY(churchId,roleId) REFERENCES roles(churchId,id) ON DELETE CASCADE, FOREIGN KEY(userId,churchId) REFERENCES user_churches(userId,churchId));
CREATE INDEX role_members_user ON role_members(churchId,userId);
-- Upstream audit DTO projection. Values are action evidence, not reconstructed PII snapshots.
CREATE VIEW audit_log_read AS SELECT id,churchId,userId,action,entityId,createdAt created, '{}' details, '' ipAddress, '' batchId, CASE WHEN action LIKE 'people.%' OR action LIKE 'member.profile.%' THEN 'person' WHEN action LIKE 'permission.%' THEN 'permission' WHEN action LIKE 'group%' OR action LIKE 'member.group.%' THEN 'group' WHEN action LIKE 'login.%' THEN 'login' ELSE 'settings' END category, CASE WHEN action LIKE 'content.%' OR action LIKE 'calendar%' THEN 'content' WHEN action LIKE 'doing.%' OR action LIKE 'tasks.%' THEN 'doing' ELSE 'membership' END module, CASE WHEN action LIKE 'people.%' OR action LIKE 'member.profile.%' THEN 'person' WHEN action LIKE 'group%' OR action LIKE 'member.group.%' THEN 'group' WHEN action LIKE 'permission.%' THEN 'role' ELSE substr(action,1,instr(action||'.','.')-1) END entityType FROM audit_log;
